:root {
  --background: #f4f6f0; /* Off-White/Light greenish background */
  --foreground: #171717;
  --agri-green: #1b4332; /* Deep agriculture green */
  --agri-light: #d8f3dc;
  --agri-accent: #52b788;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-agri-green: var(--agri-green);
  --color-agri-light: var(--agri-light);
  --color-agri-accent: var(--agri-accent);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #081c15; /* Very dark green for dark mode */
    --foreground: #ededed;
  }
}

